package org.nemo.fujibanks

import kotlinx.coroutines.runBlocking
import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import org.nemo.fujibanks.data.PhotoStore
import org.nemo.fujibanks.fuji.Recipe

/**
 * The sample-frame reference on a recipe.
 *
 * It is a field on a model that is already on disk in every library and every
 * backup, so the thing worth pinning down is that adding it did not invalidate
 * what is already saved — and that it is a reference, never the image itself.
 */
class RecipePhotoFieldTest {

    @get:Rule
    val temp = TemporaryFolder()

    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true }

    @Test
    fun `a library file written before photos existed still loads`() {
        val old = """{"name":"Kodacolor VR 200","filmSimulation":3,"dynamicRange":200}"""
        val recipe = json.decodeFromString<Recipe>(old)

        assertEquals("Kodacolor VR 200", recipe.name)
        assertNull("a recipe from before the field has no frame", recipe.photoId)
    }

    @Test
    fun `the id survives a round trip and the bytes are not in it`() {
        val recipe = Recipe(name = "Copenhagen Negative", photoId = "abc-123")
        val text = json.encodeToString(Recipe.serializer(), recipe)

        assertEquals(recipe, json.decodeFromString<Recipe>(text))
        // A recipe file is small enough to read and share; an embedded frame
        // would make it neither.
        assert(text.length < 2000) { "recipe JSON should stay small, was ${text.length}" }
    }

    @Test
    fun `duplicating a recipe shares the frame rather than copying it`() {
        val source = Recipe(name = "Eterna", photoId = "frame-1")
        val copy = source.copy(name = "Eterna copy")

        assertEquals(source.photoId, copy.photoId)
    }

    @Test
    fun `a frame does not make two otherwise equal recipes the same`() {
        val plain = Recipe(name = "Provia")
        val withFrame = plain.copy(photoId = "frame-1")

        // Equality is what the Recipes screen ticks with and what Develop's
        // chips compare, so this is worth stating rather than assuming.
        assert(plain != withFrame)
    }

    // -- The sweep, which is what actually deletes a frame ------------------
    //
    // Re-encoding needs Android's BitmapFactory and cannot run here, but the
    // deletion rule is plain file work — and it is the part that loses data if
    // it is wrong, in either direction.

    private fun store(): Pair<PhotoStore, java.io.File> {
        val dir = temp.newFolder()
        return PhotoStore(dir) to dir
    }

    private fun PhotoStore.plant(id: String) = file(id).apply { writeBytes(byteArrayOf(1, 2, 3)) }

    @Test
    fun `a frame nothing points at is deleted`() = runBlocking {
        val (photos, _) = store()
        val orphan = photos.plant("gone")
        val kept = photos.plant("held")

        photos.sweep(setOf("held"))

        assertFalse("the recipe holding it was deleted", orphan.exists())
        assertTrue(kept.exists())
    }

    @Test
    fun `a frame two recipes share survives one of them going`() = runBlocking {
        val (photos, _) = store()
        // Duplicate copies the reference, so deleting the original must not
        // take the frame out from under the copy.
        val shared = photos.plant("frame-1")

        photos.sweep(setOf("frame-1"))

        assertTrue(shared.exists())
    }

    @Test
    fun `sweeping an empty library clears the folder`() = runBlocking {
        val (photos, dir) = store()
        photos.plant("a")
        photos.plant("b")

        photos.sweep(emptySet())

        assertEquals(0, dir.listFiles()?.size ?: 0)
    }
}

package org.nemo.fujibanks

import kotlinx.coroutines.runBlocking
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import org.nemo.fujibanks.data.BackupStore
import org.nemo.fujibanks.data.SaveResult
import org.nemo.fujibanks.fuji.Bank
import org.nemo.fujibanks.fuji.BankSnapshot
import org.nemo.fujibanks.fuji.FilmSim
import org.nemo.fujibanks.fuji.Recipe

/**
 * The duplicate-suppression rule, which exists because a pile of byte-identical
 * backups told the photographer nothing about what the camera held.
 */
class BackupStoreTest {

    @get:Rule
    val temp = TemporaryFolder()

    private fun store() = BackupStore(temp.newFolder())

    private fun snapshot(takenAt: Long, vararg banks: Bank) = BankSnapshot(
        cameraModel = "X-T30 III",
        serialNumber = "SN1",
        takenAt = takenAt,
        banks = banks.toList(),
    )

    private fun bank(slot: Int, sim: Int = FilmSim.PROVIA) =
        Bank(slot, Recipe(name = "C$slot", filmSimulation = sim))

    @Test
    fun `identical banks are not saved twice`() = runBlocking {
        val store = store()
        val first = snapshot(1000, bank(1), bank(2))
        assertTrue(store.saveIfChanged(first) is SaveResult.Saved)

        val again = store.saveIfChanged(snapshot(2000, bank(1), bank(2)))
        assertTrue(again is SaveResult.Duplicate)
        assertEquals(1000L, (again as SaveResult.Duplicate).existing.takenAt)
        assertEquals(1, store.list().size)
    }

    @Test
    fun `a changed recipe is saved`() = runBlocking {
        val store = store()
        store.saveIfChanged(snapshot(1000, bank(1), bank(2)))
        val changed = snapshot(2000, bank(1), bank(2, FilmSim.ACROS))
        assertTrue(store.saveIfChanged(changed) is SaveResult.Saved)
        assertEquals(2, store.list().size)
        assertEquals(2000L, store.latest()!!.takenAt)
    }

    @Test
    fun `slot order does not count as a change`() = runBlocking {
        val store = store()
        store.saveIfChanged(snapshot(1000, bank(1), bank(2)))
        assertTrue(store.saveIfChanged(snapshot(2000, bank(2), bank(1))) is SaveResult.Duplicate)
    }

    @Test
    fun `a different slot set is saved even when the recipes match`() = runBlocking {
        val store = store()
        store.saveIfChanged(snapshot(1000, bank(1), bank(2)))
        assertTrue(store.saveIfChanged(snapshot(2000, bank(1))) is SaveResult.Saved)
    }

    /**
     * Undo restores whatever [BackupStore.latest] returns, so a save may only
     * be skipped while the newest file on disk is the twin of the one skipped —
     * never merely some older file with the same banks.
     */
    @Test
    fun `a duplicate of an older backup is still saved when a newer one differs`() = runBlocking {
        val store = store()
        store.saveIfChanged(snapshot(1000, bank(1), bank(2)))
        store.saveIfChanged(snapshot(2000, bank(1), bank(2, FilmSim.ACROS)))

        val backToTheOldBanks = snapshot(3000, bank(1), bank(2))
        assertTrue(store.saveIfChanged(backToTheOldBanks) is SaveResult.Saved)
        assertEquals(3000L, store.latest()!!.takenAt)
    }

    @Test
    fun `a snapshot from another body is never a duplicate`() = runBlocking {
        val store = store()
        store.saveIfChanged(snapshot(1000, bank(1)))
        val otherBody = snapshot(2000, bank(1)).copy(serialNumber = "SN2")
        assertTrue(store.saveIfChanged(otherBody) is SaveResult.Saved)
    }
}

package org.nemo.fujibanks.ui

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
