/**
 * Recipes: paste one in, keep a library, group them into sets, put a set in the
 * camera.
 *
 * Installing a set replaces all seven banks at once, which is the whole point —
 * but it also means it never happens without showing what changes first.
 */
/** What the editor is open on: one recipe from the library, or a new one. */
private sealed interface Editing {
    data class Existing(val recipe: Recipe) : Editing
    data object New : Editing
}

@Composable
fun RecipesScreen(viewModel: BanksViewModel) {
    var text by rememberSaveable { mutableStateOf("") }
    var name by rememberSaveable { mutableStateOf("") }
    var parsed by remember { mutableStateOf<TextRecipeParser.Result?>(null) }
    var packName by rememberSaveable { mutableStateOf("") }
    // Ticked recipes are held by value, not by position. Positions shift under
    // the selection — Duplicate inserts at index+1 — and the tick would silently
    // move to a different recipe, which then went into the camera.
    var selected by remember { mutableStateOf(setOf<Recipe>()) }
    var editing by remember { mutableStateOf<Editing?>(null) }
    var installing by remember { mutableStateOf<Recipe?>(null) }
    var deletingPack by remember { mutableStateOf<RecipePack?>(null) }
    var replacingPack by remember { mutableStateOf<RecipePack?>(null) }

    val listState = rememberLazyListState()
    val scope = rememberCoroutineScope()

    // Sets live at the top of the list, so making one from the button at the
    // bottom used to insert a card above the viewport and shove everything
    // down under the finger. Go to it instead — that is also the only
    // confirmation that the set now exists.
    fun madeSet() = scope.launch { listState.animateScrollToItem(0) }

    // Parsing hangs off the text rather than off each keystroke: the preview
    // is a variable-height card sitting between the two fields, so rebuilding
    // it on every character made the field below it slide around while it was
    // being typed into.
    LaunchedEffect(text, name) {
        if (text.isBlank()) { parsed = null; return@LaunchedEffect }
        delay(200)
        parsed = TextRecipeParser.parse(text, name)
    }

    val recipes by viewModel.recipes.collectAsState()
    val packs by viewModel.savedPacks.collectAsState()

    // The editor holds the recipe itself, not its row number: duplicating one
    // inserts at index + 1, and a stored position quietly became a different
    // recipe the moment the list moved under it.
    when (val open = editing) {
        null -> Unit
        is Editing.New -> {
            // Without this, Back from the editor closes the app and takes the
            // unsaved edits with it.
            BackHandler { editing = null }
            RecipeEditorScreen(
                viewModel = viewModel,
                initial = Recipe(),
                onSave = { viewModel.saveRecipe(it); editing = null },
                onCancel = { editing = null },
                onDelete = null,
            )
            return
        }
        is Editing.Existing -> {
            BackHandler { editing = null }
            RecipeEditorScreen(
                viewModel = viewModel,
                initial = open.recipe,
                onSave = { viewModel.updateRecipe(open.recipe, it); editing = null },
                onCancel = { editing = null },
                onDelete = { viewModel.deleteRecipe(open.recipe); editing = null },
            )
            return
        }
    }

    LazyColumn(
        Modifier.fillMaxSize(),
        state = listState,
        contentPadding = PaddingValues(16.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        // -- Building one by hand, no camera needed --------------------------
        item {
            Button(
                onClick = { editing = Editing.New },
                colors = ButtonDefaults.buttonColors(
                    containerColor = Film.Accent,
                    contentColor = Film.Background,
                ),
            ) { Text("Create a recipe") }
        }

        // -- Sets, first: this is what gets used day to day ------------------
        item { BlockLabel("SETS") }
        if (packs.isEmpty()) {
            item {
                EmptyNote(
                    title = "No sets yet",
                    body = "A set is up to seven recipes in the order they go into " +
                        "C1–C7. Build the library below, tick the ones you want, " +
                        "and name the set.",
                )
            }
        } else {
            items(packs) { pack ->
                PackCard(
                    pack = pack,
                    onInstall = { viewModel.stageWrite(pack) },
                    onDelete = { deletingPack = pack },
                )
            }
        }
        item { Spacer(Modifier.height(4.dp)) }

        // -- Adding a recipe -------------------------------------------------
        item { BlockLabel("ADD A RECIPE") }
        item {
            Text(
                "Paste one from Fuji X Weekly, or anywhere it is written out as text.",
                style = MaterialTheme.typography.bodySmall,
                color = Film.TextMuted,
            )
        }
        item {
            OutlinedTextField(
                value = text,
                onValueChange = { text = it },
                placeholder = {
                    Text(
                        "Classic Chrome\nDynamic Range: DR400\nHighlight: +1\n…",
                        color = Film.TextMuted,
                    )
                },
                modifier = Modifier.fillMaxWidth().height(180.dp),
                textStyle = MaterialTheme.typography.bodySmall.copy(
                    fontFamily = FontFamily.Monospace
                ),
                colors = fujiFieldColors(),
            )
        }
        item {
            OutlinedTextField(
                value = name,
                onValueChange = { name = it },
                label = { Text("Name (optional)") },
                modifier = Modifier.fillMaxWidth(),
                singleLine = true,
                colors = fujiFieldColors(),
            )
        }

        parsed?.let { result ->
            item { ParsePreview(result) }
            item {
                Button(
                    onClick = {
                        viewModel.saveRecipe(result.recipe)
                        text = ""; name = ""; parsed = null
                    },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = Film.Accent,
                        contentColor = Film.Background,
                    ),
                ) { Text("Save to library") }
            }
        }

        // -- Library ---------------------------------------------------------
        if (recipes.isEmpty()) {
            item {
                Spacer(Modifier.height(4.dp))
                BlockLabel("LIBRARY")
                EmptyNote(
                    title = "The library is empty",
                    body = "Paste a recipe above, build one by hand, or read the " +
                        "camera and save a bank you already have.",
                )
            }
        } else {
            item {
                Spacer(Modifier.height(4.dp))
                BlockLabel("LIBRARY (${recipes.size})")
                Text(
                    "Tick up to seven, name the set, and it is ready to install.",
                    style = MaterialTheme.typography.bodySmall,
                    color = Film.TextMuted,
                )
            }
            items(recipes) { row ->
                RecipeRow(
                    recipe = row,
                    checked = row in selected,
                    // Seven banks, seven recipes: past that the toggle used to
                    // do nothing at all while still looking like a button.
                    canCheck = row in selected || selected.size < FujiProps.SLOT_COUNT,
                    onToggle = {
                        selected =
                            if (row in selected) selected - row
                            else if (selected.size < FujiProps.SLOT_COUNT) selected + row
                            else selected
                    },
                    onEdit = { editing = Editing.Existing(row) },
                    onInstall = { installing = row },
                    onDuplicate = { viewModel.duplicateRecipe(row) },
                )
            }
            if (selected.isNotEmpty()) {
                item {
                    Column {
                        OutlinedTextField(
                            value = packName,
                            onValueChange = { packName = it },
                            label = { Text("Set name") },
                            modifier = Modifier.fillMaxWidth(),
                            singleLine = true,
                            colors = fujiFieldColors(),
                        )
                        Spacer(Modifier.height(8.dp))
                        Button(
                            enabled = packName.isNotBlank(),
                            onClick = {
                                // Order follows the library, not the order they
                                // were ticked in, so the slots they land in are
                                // the ones shown on screen.
                                val pack = RecipePack(
                                    packName,
                                    recipes.filter { it in selected },
                                )
                                // savePack replaces by name without a word.
                                if (packs.any { it.name == pack.name }) {
                                    replacingPack = pack
                                } else {
                                    viewModel.savePack(pack)
                                    packName = ""
                                    selected = emptySet()
                                    madeSet()
                                }
                            },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = Film.Accent,
                                contentColor = Film.Background,
                            ),
                        ) { Text("Make a set of ${selected.size}") }
                        if (packName.isBlank()) {
                            Spacer(Modifier.height(4.dp))
                            Text("THE SET NEEDS A NAME", style = LabelCaps)
                        }
                    }
                }
            }
        }
    }

    installing?.let { recipe ->
        InstallSlotDialog(
            recipe = recipe,
            onInstall = { slot ->
                viewModel.stageSingle(recipe, slot)
                installing = null
            },
            onCancel = { installing = null },
        )
    }

    // Deleting a set has no way back, so it asks — the same treatment deleting
    // a backup already gets.
    deletingPack?.let { pack ->
        FujiDialog(
            title = "Delete “${pack.name}”?",
            subtitle = "Only the grouping goes — the ${pack.recipes.size} recipes stay.",
            onDismiss = { deletingPack = null },
            cancel = DialogAction("Keep it") { deletingPack = null },
            confirm = DialogAction("Delete") {
                viewModel.deletePack(pack.name)
                deletingPack = null
            },
            destructive = true,
        )
    }

    replacingPack?.let { pack ->
        FujiDialog(
            title = "Replace the set “${pack.name}”?",
            subtitle = "That name is taken. Saving replaces it with these " +
                "${pack.recipes.size} recipes.",
            onDismiss = { replacingPack = null },
            cancel = DialogAction("Cancel") { replacingPack = null },
            confirm = DialogAction("Replace") {
                viewModel.savePack(pack)
                packName = ""
                selected = emptySet()
                replacingPack = null
                madeSet()
            },
            destructive = true,
        )
    }
}

/** Choosing which bank a single recipe should land in. */
@Composable
private fun InstallSlotDialog(
    recipe: Recipe,
    onInstall: (Int) -> Unit,
    onCancel: () -> Unit,
) {
    var slot by remember { mutableStateOf(1) }
    FujiDialog(
        title = "Install “${recipe.name.ifEmpty { "unnamed" }}”",
        subtitle = "One bank. The other six are left alone.",
        onDismiss = onCancel,
        cancel = DialogAction("Cancel", onClick = onCancel),
        confirm = DialogAction("Continue") { onInstall(slot) },
    ) {
        SlotPicker(selected = setOf(slot), onToggle = { slot = it })
    }
}

@Composable
private fun PackCard(pack: RecipePack, onInstall: () -> Unit, onDelete: () -> Unit) {
    Column(
        Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(12.dp))
            .background(Film.Surface)
            .border(1.dp, Film.Outline, RoundedCornerShape(12.dp))
            .padding(14.dp),
    ) {
        Text(
            pack.name,
            style = MaterialTheme.typography.titleSmall,
            fontWeight = FontWeight.SemiBold,
            color = Film.TextPrimary,
        )
        Text(
            "${pack.recipes.size} recipes",
            style = MaterialTheme.typography.bodySmall,
            color = Film.TextMuted,
        )

        Spacer(Modifier.height(10.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
            pack.recipes.forEach { recipe ->
                Box(
                    Modifier
                        .size(width = 38.dp, height = 28.dp)
                        .clip(RoundedCornerShape(3.dp))
                ) {
                    RecipeFrame(recipe, Modifier.fillMaxSize(), width = 38.dp, showCurve = false)
                }
            }
        }

        Spacer(Modifier.height(12.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(
                onClick = onInstall,
                colors = ButtonDefaults.buttonColors(
                    containerColor = Film.Accent,
                    contentColor = Film.Background,
                ),
            ) { Text("Install in camera") }
            TextButton(onClick = onDelete) { Text("Delete", color = Film.TextMuted) }
        }
    }
}

@Composable
private fun RecipeRow(
    recipe: Recipe,
    checked: Boolean,
    canCheck: Boolean,
    onToggle: () -> Unit,
    onEdit: () -> Unit,
    onInstall: () -> Unit,
    onDuplicate: () -> Unit,
) {
    Column(
        Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(10.dp))
            .background(if (checked) Film.SurfaceRaised else Film.Surface)
            .border(
                1.dp,
                if (checked) Film.Accent else Film.Outline,
                RoundedCornerShape(10.dp),
            )
            .padding(10.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Box(
                Modifier
                    .size(width = 52.dp, height = 38.dp)
                    .clip(RoundedCornerShape(4.dp))
                    .clickable(onClick = onEdit)
            ) {
                RecipeFrame(recipe, Modifier.fillMaxSize(), width = 52.dp, showCurve = false)
            }
            Spacer(Modifier.width(12.dp))
            Column(Modifier.weight(1f).clickable(onClick = onEdit)) {
                Text(
                    recipe.name.ifEmpty { "unnamed" },
                    style = MaterialTheme.typography.bodyMedium,
                    fontWeight = FontWeight.SemiBold,
                    color = Film.TextPrimary,
                )
                Text(
                    recipe.summary(),
                    style = MaterialTheme.typography.bodySmall,
                    color = Film.TextMuted,
                )
            }
            TextButton(onClick = onToggle, enabled = canCheck) {
                Text(
                    if (checked) "In set" else "To set",
                    color = when {
                        checked -> Film.Accent
                        canCheck -> Film.TextSecondary
                        else -> Film.TextMuted
                    },
                )
            }
        }
        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
            TextButton(onClick = onEdit) { Text("Edit", color = Film.TextSecondary) }
            TextButton(onClick = onDuplicate) { Text("Duplicate", color = Film.TextSecondary) }
            TextButton(onClick = onInstall) { Text("Install alone", color = Film.Accent) }
        }
    }
}

/** What the parser understood, and what it did not. Nothing is dropped quietly. */
@Composable
private fun ParsePreview(result: TextRecipeParser.Result) {
    Column(
        Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(12.dp))
            .background(Film.Surface)
            .border(1.dp, Film.Outline, RoundedCornerShape(12.dp)),
    ) {
        Box(Modifier.fillMaxWidth().height(90.dp)) {
            RecipeArtwork(result.recipe, Modifier.fillMaxSize())
        }
        Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(3.dp)) {
            Text(
                result.recipe.summary(),
                fontWeight = FontWeight.SemiBold,
                color = Film.TextPrimary,
            )
            Spacer(Modifier.height(4.dp))

            val mono = MaterialTheme.typography.bodySmall.copy(fontFamily = FontFamily.Monospace)
            result.recognized.forEach {
                Text("✓ ${it.line}", style = mono, color = Film.Good)
            }
            result.ignored.forEach {
                Text("• $it", style = mono, color = Film.Warn)
            }
            if (result.ignored.isNotEmpty()) {
                Text(
                    "A bank cannot hold these — kept as a note, set them on the camera.",
                    style = MaterialTheme.typography.labelSmall,
                    color = Film.TextMuted,
                )
            }
            result.unrecognized.forEach {
                Text("? $it", style = mono, color = Film.Bad)
            }
            if (result.unrecognized.isNotEmpty()) {
                Text(
                    "Not understood — check these against the original.",
                    style = MaterialTheme.typography.labelSmall,
                    color = Film.TextMuted,
                )
            }
        }
    }
}

package org.nemo.fujibanks

import org.junit.Assert.assertEquals
import org.junit.Test
import org.nemo.fujibanks.fuji.Darkroom
import org.nemo.fujibanks.fuji.Recipe
import org.nemo.fujibanks.fuji.WhiteBalance
import java.nio.ByteBuffer
import java.nio.ByteOrder

/**
 * The D185 conversion profile patch.
 *
 * These cover what the patch is *known* to do: it touches the fields it was
 * asked for and nothing else, it leaves the whole white-balance block alone on
 * As Shot, and it gates colour temperature on the mode that allows it.
 *
 * They deliberately assert nothing about the *value* written for the
 * white-balance mode. Every bank on Color Temperature still renders green and
 * the meaning of index 12 is unknown — see `Darkroom.patch`. A test that
 * froze the current guess would only make the next fix look like a regression.
 */
class DarkroomTest {

    /** A profile shaped like the camera's: a count, then int32s at the end. */
    private fun profile(params: Int = 32, fill: Int = SENTINEL): ByteArray {
        val bytes = ByteArray(64 + params * 4)
        val buf = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
        buf.putShort(0, params.toShort())
        for (i in 0 until params) buf.putInt(64 + i * 4, fill)
        return bytes
    }

    private fun field(profile: ByteArray, index: Int): Int = Darkroom.fields(profile)[index]

    /** Write one parameter into a profile, the way the camera would have. */
    private fun setField(profile: ByteArray, index: Int, value: Int) {
        val buf = ByteBuffer.wrap(profile).order(ByteOrder.LITTLE_ENDIAN)
        val params = buf.getShort(0).toInt() and 0xFFFF
        buf.putInt(profile.size - params * 4 + index * 4, value)
    }

    @Test
    fun `the white balance mode is never written into the profile`() {
        // Index 12 is not the mode. A profile read off the camera holds 0 there
        // for a frame shot on a bank set to Auto, while the shift fields hold
        // that bank's real values — so whatever [12] records, it is not this.
        // Writing 0x8007 into it turned every Color Temperature bank green.
        for (mode in listOf(WhiteBalance.AUTO, WhiteBalance.DAYLIGHT, WhiteBalance.COLOR_TEMP, WhiteBalance.SHADE)) {
            val out = Darkroom.patch(profile(), Recipe(whiteBalance = mode))
            assertEquals("mode 0x%04X must leave [12] alone".format(mode), SENTINEL, field(out, WB_MODE))
        }
    }

    @Test
    fun `a named mode still carries its shifts and its kelvin`() {
        val out = Darkroom.patch(
            profile(),
            Recipe(whiteBalance = WhiteBalance.COLOR_TEMP, wbColorTemp = 6600, wbShiftR = -1, wbShiftB = -3),
        )
        assertEquals(-1, field(out, WB_SHIFT_R))
        assertEquals(-3, field(out, WB_SHIFT_B))
        assertEquals(6600, field(out, WB_TEMP))
    }

    @Test
    fun `as shot leaves the whole white balance block alone`() {
        val out = Darkroom.patch(profile(), Recipe(whiteBalance = WhiteBalance.AS_SHOT, wbShiftR = 5))

        // Untouched means the RAF's own EXIF still wins; writing 0 would not be
        // the same thing, it would be an explicit "use EXIF" on top of a shift.
        assertEquals(SENTINEL, field(out, WB_MODE))
        assertEquals(SENTINEL, field(out, WB_SHIFT_R))
        assertEquals(SENTINEL, field(out, WB_TEMP))
    }

    @Test
    fun `colour temperature is only written on the mode that gates it`() {
        val out = Darkroom.patch(profile(), Recipe(whiteBalance = WhiteBalance.DAYLIGHT, wbColorTemp = 6600))
        assertEquals(SENTINEL, field(out, WB_TEMP))
    }

    @Test
    fun `shifts go through signed`() {
        val out = Darkroom.patch(profile(), Recipe(whiteBalance = WhiteBalance.COLOR_TEMP, wbShiftR = -1, wbShiftB = -3))
        assertEquals(-1, field(out, WB_SHIFT_R))
        assertEquals(-3, field(out, WB_SHIFT_B))
    }

    @Test
    fun `a patch changes nothing but the fields it was asked for`() {
        val base = profile()
        val out = Darkroom.patch(base, Recipe(whiteBalance = WhiteBalance.AS_SHOT))
        assertEquals(base.size, out.size)
        // The header and everything before the parameter block survive intact.
        assertEquals(
            base.copyOf(64).toList(),
            out.copyOf(64).toList(),
        )
    }

    @Test
    fun `dynamic range goes through as asked, even past what the frame can do`() {
        // Clamping this was tried and taken back out: converting at a DR the
        // recipe does not name is a substitution, and Develop explains the
        // mismatch instead of quietly resolving it. The wrong-looking frame is
        // the honest answer to a recipe the frame cannot support.
        val shotAt100 = profile().also { setField(it, DR, 100) }

        for (asked in listOf(100, 200, 400)) {
            val out = Darkroom.patch(shotAt100, Recipe(dynamicRange = asked))
            assertEquals(asked, field(out, DR))
        }
    }

    @Test
    fun `the ceiling is the frame's own dynamic range`() {
        // Not used to clamp — used by Develop to decide whether to warn.
        assertEquals(100, Darkroom.dynamicRangeCeiling(profile().also { setField(it, DR, 100) }))
        assertEquals(200, Darkroom.dynamicRangeCeiling(profile().also { setField(it, DR, 200) }))
        assertEquals(400, Darkroom.dynamicRangeCeiling(profile().also { setField(it, DR, 400) }))
    }

    @Test
    fun `an unreadable ceiling reports the top of the range, so nothing is warned about`() {
        val odd = profile().also { setField(it, DR, 12345) }
        assertEquals(400, Darkroom.dynamicRangeCeiling(odd))
    }

    private companion object {
        /** 0x8000 sign-extended: the camera's "not set" in a 32-bit field. */
        const val SENTINEL = -32768
        const val WB_MODE = 12
        const val WB_SHIFT_R = 13
        const val WB_SHIFT_B = 14
        const val WB_TEMP = 15
        const val DR = 6
    }
}

package org.nemo.fujibanks

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import org.nemo.fujibanks.fuji.Codec
import org.nemo.fujibanks.fuji.DynamicRange
import org.nemo.fujibanks.fuji.Effect
import org.nemo.fujibanks.fuji.FilmSim
import org.nemo.fujibanks.fuji.FujiProps
import org.nemo.fujibanks.fuji.Grain
import org.nemo.fujibanks.fuji.Recipe
import org.nemo.fujibanks.fuji.WhiteBalance
import org.nemo.fujibanks.usb.packI16
import org.nemo.fujibanks.usb.packU16

class CodecTest {

    // -- Tone x10 ----------------------------------------------------------

    @Test
    fun `tone round trips through x10 encoding`() {
        for (tenths in -80..80) {
            val value = tenths / 10.0
            assertEquals(value, Codec.decodeTone(Codec.encodeTone(value)), 0.0001)
        }
    }

    @Test
    fun `tone encodes half steps`() {
        assertEquals(15, Codec.encodeTone(1.5))
        assertEquals(-25, Codec.encodeTone(-2.5))
        assertEquals(1.5, Codec.decodeTone(15), 0.0001)
    }

    @Test
    fun `tone sentinel decodes to zero`() {
        // The camera reports 0x8000 for "not set"; both the unsigned and the
        // sign-extended read of it must land on zero.
        assertEquals(0.0, Codec.decodeTone(0x8000), 0.0001)
        assertEquals(0.0, Codec.decodeTone(-32768), 0.0001)
    }

    // -- High ISO NR -------------------------------------------------------

    @Test
    fun `noise reduction round trips across its whole range`() {
        for (nr in -4..4) {
            assertEquals(nr, Codec.decodeNoiseReduction(Codec.encodeNoiseReduction(nr)))
        }
    }

    @Test
    fun `noise reduction encoding is the documented lookup, not a scale`() {
        // Nothing arithmetic connects these; they are observed values.
        assertEquals(0x8000, Codec.encodeNoiseReduction(-4))
        assertEquals(0x2000, Codec.encodeNoiseReduction(0))
        assertEquals(0x5000, Codec.encodeNoiseReduction(4))
        // Non-monotonic: -2 is higher than +2.
        assertEquals(0x4000, Codec.encodeNoiseReduction(-2))
        assertEquals(0x0000, Codec.encodeNoiseReduction(2))
    }

    @Test
    fun `noise reduction decodes a sign-extended read`() {
        // 0x8000 arrives as -32768 from a signed 16-bit read.
        assertEquals(-4, Codec.decodeNoiseReduction(-32768))
    }

    @Test
    fun `noise reduction clamps out-of-range input`() {
        assertEquals(0x8000, Codec.encodeNoiseReduction(-99))
        assertEquals(0x5000, Codec.encodeNoiseReduction(99))
    }

    // -- White balance -----------------------------------------------------

    @Test
    fun `white balance masks a signed read back to its mode id`() {
        // 0x8007 (Color Temp) reads as -32761 over the wire.
        assertEquals(WhiteBalance.COLOR_TEMP, Codec.decodeWhiteBalance(-32761))
        assertEquals(WhiteBalance.AUTO, Codec.decodeWhiteBalance(0x0002))
    }

    // -- Bank properties -> recipe ----------------------------------------

    @Test
    fun `recipe decodes from bank properties`() {
        val props = mapOf(
            FujiProps.FILM_SIMULATION to FilmSim.CLASSIC_CHROME,
            FujiProps.DYNAMIC_RANGE to 400,
            FujiProps.GRAIN_EFFECT to Grain.STRONG_SMALL.raw,
            FujiProps.COLOR_CHROME to Effect.STRONG.raw,
            FujiProps.SMOOTH_SKIN to Effect.OFF.raw,
            FujiProps.WHITE_BALANCE to WhiteBalance.AUTO,
            FujiProps.WB_SHIFT_R to 2,
            FujiProps.WB_SHIFT_B to -4,
            FujiProps.HIGHLIGHT_TONE to 10,
            FujiProps.SHADOW_TONE to 20,
            FujiProps.COLOR to 40,
            FujiProps.SHARPNESS to 20,
            FujiProps.HIGH_ISO_NR to 0x8000,
            FujiProps.CLARITY to 0,
        )
        val r = Codec.recipeFromProps("Kodachrome", props)

        assertEquals("Kodachrome", r.name)
        assertEquals(FilmSim.CLASSIC_CHROME, r.filmSimulation)
        assertEquals(DynamicRange.DR400, r.dynamicRange)
        assertEquals(Grain.STRONG_SMALL, r.grain)
        assertEquals(Effect.STRONG, r.colorChrome)
        assertEquals(2, r.wbShiftR)
        assertEquals(-4, r.wbShiftB)
        assertEquals(1.0, r.highlightTone, 0.0001)
        assertEquals(2.0, r.shadowTone, 0.0001)
        assertEquals(4.0, r.color, 0.0001)
        assertEquals(-4, r.noiseReduction)
    }

    @Test
    fun `monochrome recipe drops colour and keeps mono shifts`() {
        val props = mapOf(
            FujiProps.FILM_SIMULATION to FilmSim.ACROS_R,
            FujiProps.COLOR to 40,      // meaningless on a B&W simulation
            FujiProps.MONO_WC to 15,
            FujiProps.MONO_MG to -20,
        )
        val r = Codec.recipeFromProps("Acros", props)

        assertTrue(r.isMono)
        assertEquals(0.0, r.color, 0.0001)
        assertEquals(1.5, r.monoWC, 0.0001)
        assertEquals(-2.0, r.monoMG, 0.0001)
    }

    // -- Recipe -> bank properties ----------------------------------------

    private fun List<Codec.PropWrite>.byId(propId: Int) =
        firstOrNull { it.propId == propId }

    @Test
    fun `colour recipe writes Color and skips the mono shifts`() {
        val writes = Codec.propsFromRecipe(
            Recipe(filmSimulation = FilmSim.VELVIA, color = 2.0, monoWC = 1.0)
        )
        assertTrue(writes.byId(FujiProps.COLOR)!!.bytes.contentEquals(packI16(20)))
        assertNull(writes.byId(FujiProps.MONO_WC))
        assertNull(writes.byId(FujiProps.MONO_MG))
    }

    @Test
    fun `monochrome recipe skips Color entirely`() {
        // The camera rejects a Color write on a B&W simulation, and a rejection
        // is indistinguishable from a real failure — so it must never be sent.
        val writes = Codec.propsFromRecipe(
            Recipe(filmSimulation = FilmSim.ACROS, color = 3.0, monoWC = 1.5)
        )
        assertNull(writes.byId(FujiProps.COLOR))
        assertTrue(writes.byId(FujiProps.MONO_WC)!!.bytes.contentEquals(packI16(15)))
    }

    @Test
    fun `monochrome recipe omits a zero mono shift`() {
        // Writing zero to D193 D194 is refused by the camera.
        val writes = Codec.propsFromRecipe(
            Recipe(filmSimulation = FilmSim.ACROS, monoWC = 0.0, monoMG = 0.0)
        )
        assertNull(writes.byId(FujiProps.MONO_WC))
        assertNull(writes.byId(FujiProps.MONO_MG))
    }

    @Test
    fun `colour temperature is written only in Color Temp mode`() {
        val auto = Codec.propsFromRecipe(
            Recipe(whiteBalance = WhiteBalance.AUTO, wbColorTemp = 5500)
        )
        assertNull(auto.byId(FujiProps.WB_COLOR_TEMP))

        val kelvin = Codec.propsFromRecipe(
            Recipe(whiteBalance = WhiteBalance.COLOR_TEMP, wbColorTemp = 5500)
        )
        assertTrue(kelvin.byId(FujiProps.WB_COLOR_TEMP)!!.bytes.contentEquals(packU16(5500)))
    }

    @Test
    fun `a skipped property is not resurrected from the baseline`() {
        // The bank already holds a Color value; a B&W recipe must still not
        // write one, rather than falling back to what was there.
        val base = mapOf(FujiProps.COLOR to packI16(40))
        val writes = Codec.propsFromRecipe(Recipe(filmSimulation = FilmSim.ACROS), base)
        assertNull(writes.byId(FujiProps.COLOR))
    }

    @Test
    fun `unmodelled properties are preserved from the baseline`() {
        val base = mapOf(FujiProps.IMAGE_SIZE to packU16(3))
        val writes = Codec.propsFromRecipe(Recipe(), base)
        assertTrue(writes.byId(FujiProps.IMAGE_SIZE)!!.bytes.contentEquals(packU16(3)))
    }

    @Test
    fun `writes follow the order the camera requires`() {
        val writes = Codec.propsFromRecipe(
            Recipe(whiteBalance = WhiteBalance.COLOR_TEMP, wbColorTemp = 5500)
        )
        val ids = writes.map { it.propId }
        // Film simulation must precede the parameters it gates.
        assertTrue(ids.indexOf(FujiProps.FILM_SIMULATION) < ids.indexOf(FujiProps.COLOR))
        // WB mode must precede the colour temperature.
        assertTrue(ids.indexOf(FujiProps.WHITE_BALANCE) < ids.indexOf(FujiProps.WB_COLOR_TEMP))
    }

    @Test
    fun `bank round trips from recipe to properties and back`() {
        // The strongest guarantee available without a camera: encode a recipe,
        // decode what would land in the bank, and require the same recipe back.
        val original = Recipe(
            name = "Round Trip",
            filmSimulation = FilmSim.CLASSIC_NEG,
            dynamicRange = DynamicRange.DR400,
            grain = Grain.WEAK_LARGE,
            colorChrome = Effect.WEAK,
            colorChromeFxBlue = Effect.STRONG,
            smoothSkin = Effect.OFF,
            whiteBalance = WhiteBalance.COLOR_TEMP,
            wbShiftR = 3,
            wbShiftB = -5,
            wbColorTemp = 5500,
            highlightTone = -1.5,
            shadowTone = 2.0,
            color = 4.0,
            sharpness = -2.0,
            clarity = 3.0,
            noiseReduction = -3,
        )

        val decoded = Codec.recipeFromProps(
            original.name,
            Codec.propsFromRecipe(original).associate { it.propId to Codec.decodeInt(it.bytes) },
        )

        assertEquals(original, decoded)
    }

    @Test
    fun `monochrome bank round trips`() {
        val original = Recipe(
            name = "Acros Push",
            filmSimulation = FilmSim.ACROS_R,
            dynamicRange = DynamicRange.DR200,
            grain = Grain.STRONG_LARGE,
            whiteBalance = WhiteBalance.DAYLIGHT,
            highlightTone = 1.0,
            shadowTone = 2.5,
            sharpness = 1.0,
            noiseReduction = 4,
            monoWC = 2.0,
            monoMG = -1.0,
        )

        val decoded = Codec.recipeFromProps(
            original.name,
            Codec.propsFromRecipe(original).associate { it.propId to Codec.decodeInt(it.bytes) },
        )

        assertEquals(original, decoded)
        assertFalse(decoded.color != 0.0)
    }
}

